/**
 * Build hand-written Box byte/event operation groups from a SDK client.
 *
 * @example
 * ```ts
 * import { makeStreamingOperations } from "@beep/box"
 * import { Effect } from "effect"
 *
 * const operations = makeStreamingOperations({
 *   uploads: {
 *     uploadFile: () => Promise.resolve({ entries: [], totalCount: 1 })
 *   }
 * })
 *
 * const program = operations.uploads.uploadFile({
 *   requestBody: {
 *     attributes: {
 *       name: "document.txt",
 *       parent: { id: "0" }
 *     },
 *     file: new Uint8Array([104, 105])
 *   }
 * })
 *
 * Effect.runPromise(program).then((files) => console.log(files.totalCount))
 * ```
 *
 * @category constructors
 * @since 0.0.0
 */

/**
 * Experimental schema anchor for Box AI taxonomy resources returned by AI classification workflows.
 *
 * @remarks
 * This experimental domain class currently declares an empty schema shape; generated Box SDK payload schemas remain the field-level source for API data until fields are promoted here.
 *
 * @example
 * ```ts
 * import { AiTaxonomy } from "@beep/box/experimental/domain/entities/AiTaxonomy/AiTaxonomy.model";
 * import * as S from "effect/Schema";
 *
 * const decoded = S.decodeUnknownSync(AiTaxonomy)({});
 * const encoded: AiTaxonomy.Encoded = S.encodeSync(AiTaxonomy)(decoded);
 *
 * console.log(JSON.stringify(encoded));
 * ```
 *
 * @category entities
 * @since 0.0.0
 */

